#include <stdio.h>
#include <string.h>
#include <stdbool.h>

char* firstWord(const char* s) {
    static char result[1024];
    int i = 0;
    int j = 0;

    if (s == NULL) {
        result[0] = '\0';
        return result;
    }

    int len = strlen(s);

    while (i < len && s[i] == ' ') {
        i++;
    }

    while (i < len && s[i] != ' ') {
        result[j] = s[i];
        j++;
        i++;
    }

    result[j] = '\0';
    return result;
}

int main() {
    printf("%s\n", firstWord("hello world"));
    printf("%s\n", firstWord("   leading spaces"));
    printf("%s\n", firstWord("single"));
    printf("%s\n", firstWord(""));
    printf("%s\n", firstWord("    "));
    printf("%s\n", firstWord("multiple   spaces   between"));
    printf("%s\n", firstWord("trailing   "));

    return 0;
}

