import java.util.*;

public class Solution {
    public static String firstWord(String s) {
        if (s == null) {
            return "";
        }
        int first = 0;
        int second = 0;
        int n = s.length();
        while (first < n && s.charAt(first) == ' ') {
            first++;
        }
        if (first >= n) {
            return "";
        }
        second = first;
        while (second < n && s.charAt(second) != ' ') {
            second++;
        }
        return s.substring(first, second);
    }

    public static void main(String[] args) {
        System.out.println(firstWord("hello world"));
        System.out.println(firstWord("   leading spaces"));
        System.out.println(firstWord("single"));
        System.out.println(firstWord(""));
        System.out.println(firstWord("   "));
        System.out.println(firstWord("multiple   spaces   between"));
        System.out.println(firstWord("trailing   "));
    }
}
